import{_ as e,o as a,c as n,a2 as s}from"./chunks/framework.CHX4lV2z.js";const u=JSON.parse('{"title":"TokenPilot Overview","description":"","frontmatter":{},"headers":[],"relativePath":"plugin-catalog/tokenpilot/overview.md","filePath":"plugin-catalog/tokenpilot/overview.md","lastUpdated":1789811186000}'),o={name:"plugin-catalog/tokenpilot/overview.md"};function i(l,t,r,p,d,c){return a(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="tokenpilot-overview" tabindex="-1">TokenPilot Overview <a class="header-anchor" href="#tokenpilot-overview" aria-label="Permalink to &quot;TokenPilot Overview&quot;">​</a></h1><p>TokenPilot is LightRSI&#39;s first <strong>context-management preset</strong>. It composes cache-aware context policies for long-running agent sessions, with the goal of reducing token usage and cost.</p><p><a href="/LightRSI/user-guide/context-cleaner">Context Cleaner</a> is the user-facing product for reviewing tasks and approving a specific cleanup. It reuses shared task and host rewrite capabilities; its interactive workflow is distinct from TokenPilot&#39;s automatic runtime policies.</p><h2 id="what-tokenpilot-does" tabindex="-1">What TokenPilot Does <a class="header-anchor" href="#what-tokenpilot-does" aria-label="Permalink to &quot;What TokenPilot Does&quot;">​</a></h2><p>Agent sessions grow. Every turn adds more messages, more tool outputs, more context. The model sees all of it, and you pay for all of it. Much of that context is repetitive — identical prefixes sent every turn, bloated tool outputs, stale history.</p><p>TokenPilot addresses this with three techniques:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                 TokenPilot Pipeline                   │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  1. Stable Prefix                                    │</span></span>
<span class="line"><span>│     Rewrites context into cache-stable form           │</span></span>
<span class="line"><span>│     → Higher cache hit rate                          │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  2. Context Reduction                                │</span></span>
<span class="line"><span>│     Trims oversized tool output before it pollutes   │</span></span>
<span class="line"><span>│     → Leaner context per turn                        │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  3. Context Eviction                                 │</span></span>
<span class="line"><span>│     Limits how much old context is carried forward   │</span></span>
<span class="line"><span>│     → Sessions don&#39;t grow unbounded                  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Evaluation&quot;">​</a></h2><p>TokenPilot is evaluated on PinchBench and Claw-Eval in isolated and continuous modes. Benchmark tasks, runners, configurations, and current results are maintained in the separate <a href="https://github.com/Xubqpanda/TokenPilot" target="_blank" rel="noreferrer">TokenPilot experiment repository</a>; see <a href="/LightRSI/plugin-catalog/tokenpilot/benchmarks">Benchmarks</a> for the reproduction entrypoint.</p><h2 id="supported-hosts" tabindex="-1">Supported Hosts <a class="header-anchor" href="#supported-hosts" aria-label="Permalink to &quot;Supported Hosts&quot;">​</a></h2><p>TokenPilot integrates with four hosts. DeepSeek Harness uses a native Cordis plugin for optional context eviction and session status; its setup and capabilities differ from the other adapters.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Host</th><th style="text-align:left;">Integration</th><th style="text-align:left;">Page</th></tr></thead><tbody><tr><td style="text-align:left;">OpenClaw</td><td style="text-align:left;">Native plugin slot</td><td style="text-align:left;"><a href="/LightRSI/hosts/openclaw">OpenClaw</a></td></tr><tr><td style="text-align:left;">Codex CLI</td><td style="text-align:left;">Local proxy + hooks</td><td style="text-align:left;"><a href="/LightRSI/hosts/codex">Codex</a></td></tr><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;">Local gateway + MCP</td><td style="text-align:left;"><a href="/LightRSI/hosts/claude-code">Claude Code</a></td></tr><tr><td style="text-align:left;">DeepSeek Harness</td><td style="text-align:left;">Native Cordis plugin</td><td style="text-align:left;"><a href="/LightRSI/hosts/deepseek-harness">DeepSeek Harness</a></td></tr></tbody></table><p>Feature availability varies by host. See <a href="/LightRSI/hosts/compatibility">Host Compatibility</a> and each host&#39;s setup guide before choosing configuration or commands.</p><h2 id="quick-tour" tabindex="-1">Quick Tour <a class="header-anchor" href="#quick-tour" aria-label="Permalink to &quot;Quick Tour&quot;">​</a></h2><ul><li><a href="/LightRSI/plugin-catalog/tokenpilot/installation">Installation</a> — get TokenPilot running</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/configuration">Configuration</a> — settings and defaults</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/runtime-modes">Runtime Modes</a> — conservative, normal, aggressive</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/benchmarks">Benchmarks</a> — evaluation results</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/troubleshooting">Troubleshooting</a> — common problems and fixes</li></ul>`,15)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
